-- Hospital Alerts
INSERT INTO hospital_alerts (id, headline, severity, urgency, departments_affected, recommended_action, source, date) VALUES ('al-001', 'URGENT DRUG SAFETY ALERT: CDSCO Warning on Potential Contamination of Cough Syrups', 'Critical', 'Immediate', '["Pediatrics","Emergency Medicine","Pharmacy","General Practice"]'::jsonb, 'Immediately quarantine all batches of cough syrups containing Guaifenesin or Dextromethorphan from supplier ''MedHealth Labs''. Cross-check all hospital pharmacy inventory and report stock volumes. Educate outpatient staff to advise parents against over-the-counter purchases of unverified syrups.', 'Central Drugs Standard Control Organisation (CDSCO), India', '2026-07-18') ON CONFLICT (id) DO NOTHING;
INSERT INTO hospital_alerts (id, headline, severity, urgency, departments_affected, recommended_action, source, date) VALUES ('al-002', 'NATIONWIDE SHORTAGE: Intravenous Normal Saline (0.9% NaCl) 500ml Bags', 'Urgent', 'Critical', '["Anaesthesiology","Emergency Medicine","Surgery","Critical Care","Procurement"]'::jsonb, 'Conserve existing supplies of IV saline. Transition stable oral-tolerant patients to oral hydration. Utilize smaller volume bags (100ml/250ml) where clinically feasible for medication administration. Procurement teams must source alternative approved brands immediately.', 'National Pharmaceutical Pricing Authority & Hospital Supply Consortium', '2026-07-15') ON CONFLICT (id) DO NOTHING;
INSERT INTO hospital_alerts (id, headline, severity, urgency, departments_affected, recommended_action, source, date) VALUES ('al-003', 'INFECTIOUS ALERT: Surge in Local Dengue Cases (Serotype DENV-2)', 'Monitor', 'Routine', '["Infectious Diseases","Internal Medicine","Pediatrics","Emergency Medicine","Laboratory Medicine"]'::jsonb, 'Establish immediate fever clinics and ensure rapid NS1 antigen and IgM test kits are fully stocked. DENV-2 carries a higher risk of severe dengue (dengue hemorrhagic fever). Implement daily platelet monitoring for patients with warning signs.', 'State Public Health Directorate / Municipal Corporation', '2026-07-10') ON CONFLICT (id) DO NOTHING;

-- Current Guidelines
INSERT INTO current_guidelines (id, condition, issuing_organization, current_recommendation, previous_recommendation, last_updated, reason_for_change, india_relevance, "references") VALUES ('g-001', 'Type 2 Diabetes', 'American Diabetes Association (ADA) / RSSDI India', 'First-line therapy should include Metformin combined with a SGLT2 inhibitor or GLP-1 receptor agonist in all patients with established atherosclerotic cardiovascular disease (ASCVD), heart failure (HF), or chronic kidney disease (CKD), independent of baseline HbA1c.', 'Metformin as the absolute first-line monotherapy for all Type 2 Diabetes patients, adding other agents only if glycemic control (HbA1c >7.0%) is not achieved after 3 months.', '2026-01-10', 'Sustained and overwhelming RCT data (such as EMPA-REG, LEADER, and SELECT trials) prove that SGLT2 inhibitors and GLP-1 receptor agonists provide profound cardiovascular and renal protection that is entirely separate from their blood-glucose-lowering properties.', 'The Research Society for the Study of Diabetes in India (RSSDI) has endorsed this, recommending generic SGLT2 inhibitors (like Dapagliflozin or Empagliflozin) early in therapy for high-risk Indian patients due to high rates of premature CAD and kidney disease.', '["ADA Standards of Care in Diabetes (2026 Update).","RSSDI consensus guidelines on early combination therapies (2025)."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO current_guidelines (id, condition, issuing_organization, current_recommendation, previous_recommendation, last_updated, reason_for_change, india_relevance, "references") VALUES ('g-002', 'Tuberculosis', 'WHO / Indian Ministry of Health (MoHFW)', 'A shortened 4-month treatment regimen (HPZM: High-dose Rifapentine, Isoniazid, Pyrazinamide, Moxifloxacin) is the preferred standard course for adults and adolescents with drug-susceptible pulmonary tuberculosis under NTEP.', 'Standard 6-month regimen consisting of 2 months of HRZE (Isoniazid, Rifampicin, Pyrazinamide, Ethambutol) and 4 months of HR (Isoniazid, Rifampicin).', '2026-06-15', 'Large-scale Phase III trials demonstrated that replacing Rifampicin with high-dose Rifapentine and Ethambutol with Moxifloxacin allowed the regimen to be safely cut to 4 months with non-inferior bacteriological cure and high safety.', 'This is a major national change under NTEP in India. All local public health clinics are actively transition-planning for full country-wide implementation by October 2026.', '["WHO Consolidated Guidelines on Tuberculosis: Module 4: Treatment (2025 Update).","MoHFW National TB Elimination Program circular No. TB-2026/04."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO current_guidelines (id, condition, issuing_organization, current_recommendation, previous_recommendation, last_updated, reason_for_change, india_relevance, "references") VALUES ('g-003', 'Pediatric Sepsis', 'Surviving Sepsis Campaign (SSC)', 'Initiate broad-spectrum empiric antimicrobials within 1 hour of recognition of septic shock. In children with sepsis-associated organ dysfunction but without shock, a diagnostic window of up to 3 hours is recommended to prevent indiscriminate antibiotic overuse.', 'Aggressive empiric broad-spectrum antibiotics within 1 hour for all suspected sepsis, regardless of the presence of shock, which contributed to antimicrobial resistance.', '2025-11-20', 'Recent cohort studies showed that a 3-hour diagnostic assessment window in stable, non-shock patients did not increase mortality and significantly reduced the unnecessary use of restricted reserve antibiotics.', 'Extremely critical for Indian pediatric units struggling with multi-drug resistant (MDR) Gram-negative bacterial infections. Rationalizes antimicrobial stewardship in ICU settings.', '["Surviving Sepsis Campaign International Guidelines for Management of Pediatric Sepsis (2025)."]'::jsonb) ON CONFLICT (id) DO NOTHING;

-- Scientific Events
INSERT INTO scientific_events (id, title, organizer, scope, event_type, target_professions, start_date, end_date, duration, venue, city, state, country, institution, format, specialties, cme_credits, cme_accreditation_body, description, objectives, abstract_deadline, registration_deadline, early_bird_deadline, early_bird_cost, cost, seats_available, seats_left, is_live, status, image_url, poster_url, keynote_speakers, speaker_profiles, schedule, venue_map_url, registration_url, submission_url, ai_summary) VALUES ('evt-local-001', 'City Hospital Inter-Departmental Grand Rounds: Sepsis Bundle Updates 2026', 'Department of Internal Medicine & Critical Care, City Civil Hospital', 'Local', 'Grand Rounds', '["MBBS","MD/MS","DM/MCh","Nursing","Allied Health Sciences","Researchers"]'::jsonb, '2026-07-28', '2026-07-28', '2 Hours (08:00 AM - 10:00 AM IST)', 'Main Auditorium, Academic Block, City Civil Hospital', 'New Delhi', 'Delhi', 'India', 'City Civil Hospital & Medical College', 'In-Person', '["General Medicine","Emergency Medicine","Anaesthesiology","Infectious Diseases","Critical Care"]'::jsonb, 2, 'Delhi Medical Council (DMC)', 'Bi-weekly departmental case discussion and protocol review focusing on updated Surviving Sepsis Campaign 2026 guidelines, lactate clearance monitoring, and early antibiotic choices in local resistance profiles.', '["Review updated 1-hour sepsis resuscitation bundles in high-volume ERs","Analyze antimicrobial stewardship in hospital-acquired multidrug-resistant pathogens","Evaluate point-of-care ultrasound (POCUS) fluid responsiveness in septic shock"]'::jsonb, NULL, '2026-07-27', NULL, NULL, 'Free for Staff & Residents', 150, 28, false, 'Approved', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=800&q=80', NULL, '["Prof. Dr. Rajesh Sharma (HOD Internal Medicine)","Dr. Meenakshi Sundaram (Critical Care Lead)"]'::jsonb, '[{"name":"Prof. Dr. Rajesh Sharma","title":"HOD Internal Medicine & Dean Academic Research","institution":"City Civil Hospital","bio":"Senior clinician with 25+ years in tropical infectious diseases and internal medicine protocol development."},{"name":"Dr. Meenakshi Sundaram","title":"Lead Intensivist","institution":"City Civil Hospital","bio":"Pioneer in bedside echocardiography and ECMO protocol standardization in critical care units."}]'::jsonb, '[{"time":"08:00 AM - 08:30 AM","title":"Case Presentation: Refractory Septic Shock in a Post-Operative Patient","speaker":"Dr. Varun Verma (Senior Resident)"},{"time":"08:30 AM - 09:15 AM","title":"Keynote: Sepsis 3.0 vs Sepsis 2026 Bundle Changes","speaker":"Prof. Dr. Rajesh Sharma"},{"time":"09:15 AM - 09:50 AM","title":"Panel Discussion & POCUS Protocol Review","speaker":"Dr. Meenakshi Sundaram & Faculty"},{"time":"09:50 AM - 10:00 AM","title":"Q&A & CME Attendance Sign-off","speaker":"All Attendees"}]'::jsonb, NULL, 'https://cityhospital.edu.in/cme/sepsis-2026', NULL, '{"executiveSummary":"Detailed review of revised Sepsis-3 bundle application in Indian government tertiary hospital settings. Emphasized targeted antibiotic administration within 60 minutes and restrictive fluid management.","keyPearls":["In septic shock, dynamic fluid responsiveness (PLR / VCI collapsibility) prevents fluid overload in 40% of cases.","Procalcitonin-guided antibiotic de-escalation reduces ICU length of stay by 1.8 days.","Empiric coverage must account for local carbapenem-resistant Enterobacterales prevalence."],"guidelinesDiscussed":["Surviving Sepsis Campaign 2026 Guidelines","DMC Antimicrobial Stewardship Charter"],"researchPapers":["NEJM 2025 Sepsis Fluid Trial","Lancet Infectious Diseases Asian Cohort Study"],"newDrugUpdates":["Cefiderocol protocol for CRE bacteremia","Sulbactam-durlobactam in Acinetobacter shock"],"practiceChangingEvidence":["Restrictive crystalloid resuscitation (30ml/kg balanced crystalloids max before vasopressor initiation)."]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO scientific_events (id, title, organizer, scope, event_type, target_professions, start_date, end_date, duration, venue, city, state, country, institution, format, specialties, cme_credits, cme_accreditation_body, description, objectives, abstract_deadline, registration_deadline, early_bird_deadline, early_bird_cost, cost, seats_available, seats_left, is_live, status, image_url, poster_url, keynote_speakers, speaker_profiles, schedule, venue_map_url, registration_url, submission_url, ai_summary) VALUES ('evt-local-002', 'Regional Hands-on Workshop: Point-of-Care Ultrasound (POCUS) in Emergency & Trauma', 'District Medical Association & AIIMS Academic Wing', 'Local', 'Hands-on Training', '["MBBS","MD/MS","DM/MCh","Emergency Medicine","Radiology","Physiotherapy"]'::jsonb, '2026-08-02', '2026-08-02', '1 Day (09:00 AM - 05:00 PM IST)', 'Simulated Clinical Skill Center, District Medical College, AIIMS Campus', 'New Delhi', 'Delhi', 'India', 'District Medical College / AIIMS', 'In-Person', '["Emergency Medicine","Radiology","General Surgery","Anaesthesiology","Orthopaedics"]'::jsonb, 6, 'State Medical Council', 'Intensive 1-day simulation workshop featuring live human models, eFAST scan protocols, cardiac subxiphoid views, lung ultrasound for pneumothorax, and USG-guided vascular access.', '["Master eFAST ultrasound window acquisitions in acute blunt polytrauma","Perform USG-guided internal jugular and femoral vein cannulations safely","Identify pulmonary interstitial syndrome and B-lines in acute decompensated heart failure"]'::jsonb, NULL, '2026-07-30', '2026-07-25', '₹1,500', '₹2,500', 40, 5, false, 'Approved', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?auto=format&fit=crop&w=800&q=80', NULL, '["Dr. Sunita Deshmukh (Emergency Sonology Director)","Dr. Vikramaditya Roy (Trauma Surgery Lead)"]'::jsonb, '[]'::jsonb, '[{"time":"09:00 AM - 10:30 AM","title":"Physics of Ultrasound & Knobology for Emergency Clinicians","speaker":"Dr. Sunita Deshmukh"},{"time":"10:30 AM - 01:00 PM","title":"Hands-on Station 1: eFAST Scan & Pneumothorax Identification","speaker":"Faculty Instructors"},{"time":"02:00 PM - 04:30 PM","title":"Hands-on Station 2: USG Vascular Access & Rapid Echo","speaker":"Dr. Vikramaditya Roy"},{"time":"04:30 PM - 05:00 PM","title":"OSCE Assessment & Certification","speaker":"All Mentors"}]'::jsonb, NULL, 'https://dma-health.org/pocus-workshop-2026', NULL, NULL) ON CONFLICT (id) DO NOTHING;
