i)"]'::jsonb, '[]'::jsonb, '[{"time":"Day 1 - 09:00 AM","title":"Plenary: Cardiometabolic Risk in South Asians - What 2026 Trials Reveal","speaker":"Prof. Dr. V. Mohan"},{"time":"Day 2 - 11:00 AM","title":"Oration: TB Elimination by 2030 - Operational Challenges and Solutions","speaker":"Dr. Soumya Swaminathan"},{"time":"Day 3 - 02:00 PM","title":"Debate: SGLT2i vs SGLT1/2 Dual Inhibitors in Non-Diabetic Heart Failure","speaker":"National Faculty Panel"}]'::jsonb, NULL, 'https://www.apicon2027.com/register', NULL, NULL) ON CONFLICT (id) DO NOTHING;
